"""Freeze eight complete earlier proposals for a preauthorship design conference."""
from copy import deepcopy
from datetime import datetime,timezone
import json,zipfile
from apply_di7_ap_as_01 import G,R,A,info,encoded
from prepare_ac5_current_interfaces_01 import at

IDS=['greater-stoneflesh','ironskin-legion','formlock','petrify-limb','metaburst','flesh-to-stone','earthstep','wind-walk']

DELTAS=[
 ('greater-stoneflesh','B','Printed +4AC, resistance to nonmagical damage and one minute conflict with Core Instantaneous metadata.','One willing target/nonconcentration60; full source provenance, strongest spell AC and Core Corruption restriction; no imported lesser half-Speed.','Ordinary defense arithmetic, same-stat arbitration, exact source type and finite clocks are inherited. Duration/recipient selection and same-caster replacement/dismissal are local proposed completions.'),
 ('ironskin-legion','B','Up to six allies receive +2AC and resistance to physical damage; Core omits a usable ongoing duration.','Willing six-recipient concentration60; physical B/P/S including magical sources; independent AC and resistance benefit, per-recipient removal and no later enrollment.','Use actual armor formula, strongest flat spell AC, typed resistance and source concentration. No metal anatomy, hit charges, proficiency or free HP.'),
 ('formlock','C','WIS failure prevents changing form or shape; duration is incomplete.','Prospective actual anatomy/size block, no rank ceiling, concentration60/no repeats; mandatory and voluntary ending remain possible; distinguish cosmetic/condition state.','Existing form precedence, concentration displacement, body/meld lineage, immunity and hidden preflight rules remain authoritative. Hard whole-Action denial is not presumed from denying only transformation.'),
 ('petrify-limb','C','One limb becomes stone: weapon drops OR movement halts.','CON admission/regular-END saves; concentration60; chosen actual anatomical role; local unchanged mass; cross-caster one-limb family; severed-part identity and form correspondence.','Whole-body Petrified is a separate explicit condition. Actual inventory, flight loss/Falling, body identity, injury and healing sources remain required.'),
 ('metaburst','C','Ally chooses STR/DEX/CON, +4 and advantage on related checks/saves.','+4 score, local24 ceiling, temporary-CON per-level recomputation, one-choice family, source-specific derived capacities; proposed inaccessible excess is not accepted globally.','Permanent advancement already recomputes attained-level floors; temporary extension is new. Capacity-only/no-healing, genuine modifier-derived values and immutable continuous meld ceilings are inherited.'),
 ('flesh-to-stone','C','Permanent stone conversion; Core Until Dispelled.','Immediate CON-gated full native Petrified/no repeat/concentration, hard-denial admission, corpse/matter persistence and local no-intake/no-rest completion.','Native Petrified defenses, times-ten body mass, ordinary life state, condition overlay, original gear and actual cure/dispel scopes remain distinct. Metabolism is not implied by the condition.'),
 ('earthstep','C','Move through stone/earth as air for one minute.','Willing recipient/concentration; actual walking 3D substrate movement, current cargo, breathing/senses; proposed backward recorded-path retreat and residual clearance.','Ordinary body normalization permits only adjacent unobstructed placement. Long retreat through prior solid substrate is a genuine local exception requiring conference, not inherited safety.'),
 ('wind-walk','C','Caster plus up to ten other creatures become gaseous; Core Instantaneous is incomplete.','Eleven willing bodies, Fly60/Hover, one hour without concentration, individual exit, root-size eligibility and full conserved body/meld accounting.','Reviewed Gaseous Form supplies a scoped comparison only: one willing Small/Medium/Large,Fly10/Hover,concentration60,1inch gap,no added resistance. Existing actual transformation and cargo predicates remain.')
]

QUESTIONS=[
 ('BD8-Q01',['greater-stoneflesh'],'Keep the printed one-minute duration over Instantaneous and select willing/nonconcentration60, or use a concentration minute?','A: retain the earlier one willing perceived creature, no concentration,60seconds. B: same recipient with concentration60.','Recommend A because the explicit minute and lower Stoneflesh nonconcentration source support the earlier local proposal; +4/broad resistance remain source promises. It does not add lesser half-Speed. Both options need explicit agreement.','Local spell completion.'),
 ('BD8-Q02',['greater-stoneflesh'],'How should its broad nonmagical resistance preserve actual provenance and Core explicit Corruption protection?','A: all truly nonmagical typed components subject to the existing Corruption exception; no immunity or quartering. B: narrow to nonmagical physical B/P/S.','Recommend A; B silently narrows the printed source. Do not reopen native Corruption law. The full final procedure must say that unnamed general resistance does not supply explicit Corruption protection, even if a component is otherwise nonmagical.','Mostly inherited; missing explicit inherited exception is a procedure clarification, not a new global rule.'),
 ('BD8-Q03',['ironskin-legion'],'Concur on willing up-to-six recipients, concentration60,physical B/P/S and independent AC/resistance benefits?','A: earlier complete proposal, finite six-recipient snapshot and concentration60. B: one-minute nonconcentration with the same source +2AC and B/P/S.','Recommend A as the narrow maintained cohort proposal. Actual spell-family AC and typed resistance remain inherited; no full-array bonus multiplication, new metal anatomy, hit charges or removal of printed resistance.','Local duration and admission choice.'),
 ('BD8-Q04',['formlock'],'Does the source block only new actual body/form/size establishment while allowing every actual ending, including voluntary rejection?','A: prospective block with ordinary source endings; a new concentration attempt can end the old form before a blocked replacement. B: freeze the currently expressed anatomy and postpone its mandatory ending.','Recommend A. B contradicts accepted finite form endpoints and body/gear conservation. Explicitly classify Petrified and local Petrify Limb rather than treating every appearance or condition change as a new form; address actual Alter Self anatomy versus illusion.','Local restriction; no global transformation or condition rewrite.'),
 ('BD8-Q05',['formlock'],'Retain one WIS admission, concentration60,no repeat save and no generating-rank ceiling?','A: earlier exact local proposal with actual named immunities and source-specific exceptions. B: add repeat WIS at each regular END or a spell-rank limit.','Recommend A to preserve the earlier proposal; B adds an unprinted limit. Actual target/body legality, known versus hidden prevention and paid commitment remain inherited, and no whole-Action guard is consumed merely for this effect-specific prevention.','Local duration/resistance design.'),
 ('BD8-Q06',['petrify-limb'],'Confirm the chosen real limb role, CON admission/regular-END saves, finite60 and one-recipient cross-caster replacement?','A: earlier role-specific single-limb proposal; one arm OR one locomotor function, no whole-body Petrified. B: cumulative independent limb records or all-limb role effects.','Recommend A to avoid unprinted multi-limb total lockdown. Review actual limb dependencies, two-handed retention, tethers, alternate locomotion and flight loss without giving every creature an invented anatomy profile.','New local condition/family rule; actual anatomy remains a prerequisite.'),
 ('BD8-Q07',['petrify-limb'],'How should a finite limb conversion survive a form with no matching limb or genuine severing?','A: earlier one anatomical identity, no remapping, suspend unmatched expression and preserve a separated part until actual source ending. B: end the spell immediately on severing or loss of correspondence.','Recommend A only if its one-body/part identity and target-death endpoint are explicit. A supplies no injury permission or regrowth; B is simpler but changes the earlier scenario. Weight/volume unchanged is a new local choice, not native Petrified x10.','Local anatomical continuity, not general injury simulation.'),
 ('BD8-Q08',['metaburst'],'Choose score versus modifier, local ceiling and temporary CON maximum-HP integration.','A: +4score up to24 without lowering an already higher score, concentration60; recompute actual per-level floors for temporary CON and then existing maximum ledger. B: +4modifier or permanent-ASI cap20 with no temporary-CON maximum change.','Recommend A as the complete earlier explicit proposal. Keep check/save advantage independent, no attack-roll advantage, no currentHP gain, no initiative reorder and no invented HD for a profile without a CON-dependent maximum. The legal d6 bases6 and later rolled1 are supplied by character foundation, not a fabricated class.','Temporary CON extension/cap are new; maximum clamp and damage separation are inherited.'),
 ('BD8-Q09',['metaburst'],'Should temporary score-related resource capacity use a new reserve or actual holder rules, and must fixed meld ceilings remain unchanged?','A: use each actual resource holder rule; where no rule exists, identify the precise unresolved holder rather than inventing a reserve. B: adopt the earlier Eye of Judgement-style inaccessible excess partition locally for every such Metaburst capacity.','Recommend A initially. Character foundation already says current RP clamps on a real RP capacity decrease; actual RP class tables are not automatically STR/DEX/CON-dependent. Neither option changes the reviewed continuous meld-chain ceilings: later STR changes never retroactively shrink or increase them. Repair the earlier sentence if it implies otherwise.','Potential systemic scope; no shared reserve is selected by this conference packet.'),
 ('BD8-Q10',['flesh-to-stone'],'Confirm one CON save for immediate permanent native Petrified with hard-denial admission and no repeat/concentration, versus a gradual multi-save conversion.','A: earlier immediate until-dispelled condition, actual immunity/hard guard, no save waiver merely from willingness. B: gradual conversion or later permanence checkpoint.','Recommend A to preserve permanent one-cast promise without importing another game. Exact condition source/body lifecycle and real removed parts must remain; no separate statueHP, free dismissal, auto-revival or object-target grant follows.','Local admission/permanence; native Petrified is inherited.'),
 ('BD8-Q11',['flesh-to-stone'],'Choose intake/rest/death timing during indefinite petrification.','A: earlier spell-only no air/food/water intake while operative, no work/beneficial-rest credit, whole daily supply interval test; actual death-save/Stable clocks and prior shortages continue. B: native Petrified only, no added metabolic exemption, with every ordinary intake requirement continuing.','Recommend A for usable indefinite stone, but explicitly discuss whole-day boundary, partial-day requirements, poison/disease suspension and loss of support during mass changes. This is not temporal stasis or resurrection; the existing condition does not itself choose this metabolism.','Genuine new local source integration with EX58; no global biology/cosmology canon.'),
 ('BD8-Q12',['earthstep'],'Retain actual walking movement, eligible substrate and current senses/breathing while deciding the forced exit exception.','A: earlier finite backward recorded-route retreat through the same eligible substrate, stopping at new incompatible conflicts with minimal residual clearance. B: ordinary same-anchor/adjacent-only normalization, leaving an embedded conflict when it cannot fit.','Recommend A as a bounded local safety design only if maximum finite route, whole-body last-open position, real cargo and blocked-return state are fully specified. Whole-body entry/exit offsets matter: a center15ft inside a wall does not imply a15ft retreat to a body fully outside. No automatic surface teleport, free forward path, air or wall vision.','Explicit source-specific exception to adjacent-only normalization.'),
 ('BD8-Q13',['wind-walk'],'Concur on eleven willing independent recipients, local Fly60/Hover, one hour/no concentration and each recipient own Action exit?','A: earlier full mist proposal including caster as required recipient and individual links. B: retain reviewed Gaseous Form Fly10/one-minute concentration for the group.','Recommend A to retain the earlier deliberate multi-recipient travel design, while labeling all speed/duration changes new. Caster death ends only its link under this proposal. All required roster/gear/space legality, no later enrollments and independent loss history remain.','Local body profile and duration; no amendment to Gaseous Form.'),
 ('BD8-Q14',['wind-walk'],'How should unsupported root sizes and one-inch clearance be handled?','A: preserve the source without an invented size cap, but require a complete actual root-size occupancy/carrying/meld procedure for each recipient before admitting that branch. B: narrow Wind Walk to reviewed Gaseous Form Small/Medium/Large.','Recommend A with explicit unresolved profile prerequisites: body guide supplies Tiny throughLarge only; no invented Huge/Gargantuan dimensions. Continuous1inch passage is not whole-body voluntary endpoint fit, no liquid/solid bypass, no split scouts, no new resistance, and no arbitrary cargo capture.','Local clearance/profile permission; missing size interfaces remain visible.')
]


def main():
    out=R/'data/director/spell_review/body_defense_8_conference_01.json'
    root=A/'body-defense8-conference-01'; report=A/'BODY_DEFENSE_8_CONFERENCE_01_CHECK.json'
    archive=A/'DD_Body_Defense_8_Conference_01.zip'; req=A/'BODY_DEFENSE_8_CONFERENCE_01_REQUEST.txt'; prep=A/'BODY_DEFENSE_8_CONFERENCE_01_PREPARATION.json'
    assert all(not p.exists() for p in [out,root,report,archive,req,prep])
    sources={};checks=[]
    def bind(p):
        b=info(p);sources[b['path']]=b;return b
    def ck(label,v):
        checks.append({'check':label,'passed':bool(v)});assert v,label
    def read(p):return json.loads(p.read_bytes())
    qp=R/'data/director/spell_review/remaining_work_queue_05.json';cp=R/'data/public/spell_playtests/catalog.json';ip=R/'data/public/spell_playtests/authored_review_index.json';rp=R/'data/director/spell_review/accepted_interface_registry_04.json'
    queue,catalog,index,registry=map(read,[qp,cp,ip,rp])
    for p in [qp,cp,ip,rp,R/'data/director/spell_review/ordinary_spell_inventory_03.json',R/'data/public/class_playtests/wizard.json',R/'data/public/class_playtests/druid.json',R/'data/public/class_playtests/cleric.json',R/'data/public/class_playtests/mage.json',R/'docs/mechanics/BODY_EQUIPMENT_PLAYTEST.md',R/'docs/mechanics/TRANSFORMATION_SPELL_PLAYTEST.md',R/'docs/mechanics/FORM_TEMP_HP_PLAYTEST.md',R/'docs/mechanics/MAXIMUM_HP_PLAYTEST.md',R/'docs/mechanics/CHARACTER_CREATION_PLAYTEST.md',R/'docs/mechanics/CHARACTER_FOUNDATION_TABLES.md',R/'docs/mechanics/CONDITIONS_PLAYTEST.md',R/'docs/mechanics/HEALING_DEATH_PLAYTEST.md',R/'docs/mechanics/DAMAGE_SHARING_PLAYTEST.md',R/'docs/mechanics/CREATURE_LIFECYCLE_PLAYTEST.md',R/'data/public/expedition_candidate/complete_candidate.json',A/'CODEX_EX58_X01_FULFILLMENT_RECEIPT.txt',R/'docs/mechanics/VIDEO_GAME_ONLY_DIRECTIVE.md',R/'tools/prepare_body_defense8_conference_01.py']:
        bind(p)
    records=[];shared={};cases=[]
    for ident in IDS:
        row=next(r for r in queue['rows'] if r['id']==ident)
        ck('Not in another active packet: '+ident,row['currentGroup'] is None)
        prior=row['previousAuthoringMapRowUnchanged']['completeEarlierProposalRecords'][0]
        p=G/prior['source']['path'];ck('Original file hash: '+ident,bind(p)==prior['source'])
        doc=read(p);record=at(doc,prior['recordPointer']);current=next(s for s in catalog['spells'] if s['id']==ident);entry=next(e for e in index['entries'] if e['id']==ident)
        ck('Complete original procedure: '+ident,record['spellId']==ident and len(record['procedure'])>100)
        ck('Full unchanged source/access: '+ident,record['fullSourceAndCurrentAccessRecord']==current)
        ck('Still pending: '+ident,entry['authoredStatus']=='pending-authored-procedure')
        records.append({'spellId':ident,'source':info(p),'recordPointer':prior['recordPointer'],'completeOriginalRecordUnchanged':deepcopy(record),'completeCurrentCatalogSourceAndAccess':deepcopy(current),'currentIndexEntry':deepcopy(entry),'status':'Historical full proposal for discussion; no new final rule or current vector selected here.'})
        shared[str(p)]={'source':info(p),'completeOriginalSharedProposalUnchanged':deepcopy(doc['sharedProposal']),'completeOriginalJointIssuesUnchanged':deepcopy(doc['explicitJointIssues'])}
        for n,t in enumerate(record['workedCases']):cases.append({'id':t.split(':',1)[0],'spellId':ident,'originalTextUnchanged':t,'source':info(p),'pointer':prior['recordPointer']+f'/workedCases/{n}','status':'Original scenario obligation; conditional numeric description, not a fully sourced new current encounter.'})
        for key in ['catalog','core']:ck('Underlying '+key+': '+ident,bind(R/current['source'][key+'Path'])['sha256']==current['source'][key+'Sha256'])
    inherited=[]
    for n in list(range(15))+[22,36,39,40,49,50,51,81,82,86]:
        e=registry['entries'][n];b=e['currentAuthoritativeSource'];actual=bind(G/b['path'])
        ck('Accepted interface binding '+str(n),actual['bytes']==b['bytes'] and actual['sha256']==b['sha256'])
        inherited.append({'registryPointer':f'/entries/{n}','completeEntryUnchanged':deepcopy(e),'scopeLimit':'Existing exact source scope only; do not promote source-specific exceptions to global rules.'})
    counterparts=[]
    for ident in ['stoneflesh','shield','alter-self','gaseous-form','polymorph','shapechange','true-polymorph','mass-polymorph']:
        entry=next(e for e in index['entries'] if e['id']==ident);ck('Reviewed counterpart '+ident,entry['authoredStatus']=='reviewed-authored-operational-playtest')
        p=(ip.parent/entry['procedureFile']).resolve();doc=read(p);ptr=entry.get('wholeCardPointer',entry['procedurePointer'])
        counterparts.append({'spellId':ident,'source':bind(p),'pointer':ptr,'completeCurrentCard':deepcopy(at(doc,ptr)),'completeSharedRules':deepcopy(doc.get('sharedRules',{})),'indexEntry':deepcopy(entry)})
    eyep=R/'data/director/spell_proposals/divination_rank6.json';eye=read(eyep);n=next(i for i,s in enumerate(eye['records']) if s['spellId']=='eye-of-judgement')
    pending=[{'spellId':'eye-of-judgement','source':bind(eyep),'pointer':f'/records/{n}','completeOriginalRecordUnchanged':deepcopy(eye['records'][n]),'completeOriginalSharedProposalUnchanged':deepcopy(eye['sharedProposal']),'status':'Unadopted proposal; cannot authorize a generic inaccessible-resource reserve.'}]
    semantic=[{'spellId':i,'riskTier':tier,'exactSourcePromiseAndGap':promise,'newChoicesForConference':choices,'inheritedScope':inherit,'sourcePreserved':True} for i,tier,promise,choices,inherit in DELTAS]
    questions=[{'id':qid,'spellIds':ids,'question':q,'options':opts,'recommendationAndConsequences':rec,'scope':scope,'decisionAlreadySelected':False} for qid,ids,q,opts,rec,scope in QUESTIONS]
    findings=[
      {'id':'BD8-F01','classification':'PROCEDURE CLARIFICATION / ACCEPTED INTERFACE','spellIds':['greater-stoneflesh'],'finding':'Broad nonmagical resistance must retain the existing explicit-protection Corruption exception; actual provenance alone does not waive that rule. Preserve the broad printed nonmagical promise for all otherwise eligible types.'},
      {'id':'BD8-F02','classification':'INTERFACE CONFLICT / OPEN DESIGN QUESTION','spellIds':['metaburst'],'finding':'Current body rules freeze continuous meld Load/pound ceilings at chain entry and never shrink them retroactively on STR change. The old final sentence must not imply recalculating an existing chain. Current external inventory still uses current capacities.'},
      {'id':'BD8-F03','classification':'OPEN DESIGN QUESTION','spellIds':['metaburst'],'finding':'The proposed reserve imports a pending Eye of Judgement design. Actual RP capacity rules already clamp on decreases; STR/DEX/CON do not automatically modify class table RP. Bind each real holder before selecting a new capacity-excess rule.'},
      {'id':'BD8-F04','classification':'EXAMPLE RECONCILIATION','spellIds':['metaburst'],'finding':'Original recorded6/1 HP bases are legal through a d6 first level and actual later rolled1; use that actual class/advancement path and source-qualified healing in a future full encounter. Preserve5->7 capacity and current3 unchanged.'},
      {'id':'BD8-F05','classification':'EXAMPLE GEOMETRY / OPEN DESIGN QUESTION','spellIds':['earthstep'],'finding':'Original15ft retreat is conditional route travel from the last legal whole-body open placement, not automatically center depth15 into a wall. Explicit real5x5 body clearance and recorded entry position are required.'},
      {'id':'BD8-F06','classification':'OPEN DESIGN QUESTION','spellIds':['flesh-to-stone'],'finding':'Native Petrified supplies aging/poison/disease/defenses, but not air/food/water exemption or rest accounting. Preserve the local proposed completion for conference instead of calling it inherited.'},
      {'id':'BD8-F07','classification':'SOURCE/PROFILE LIMIT','spellIds':['wind-walk'],'finding':'No printed source size cap does not manufacture unknown Huge/Gargantuan occupancy/carrying/meld rules. Conditional larger recipients require actual completed profiles before current cases can claim legality.'},
      {'id':'BD8-F08','classification':'HISTORY / CURRENT AUTHORITY','spellIds':IDS,'finding':'Original shared baselines/status labels are historical. Current Wizard first-distinct prepared matrices use exact actual cadence; current reviewed Gaseous Form and body normalization supersede obsolete pending labels. Do not import unrelated zombie/material/portal shared clauses.'},
    ]
    ck('Eight unique pending identities',len(set(IDS))==len(records)==8)
    ck('Sixteen complete original obligations',len(cases)==len({c['id'] for c in cases})==16)
    ck('Fourteen genuine design questions',len(questions)==14)
    ck('Frozen reviewed/pending count',index['authoredCounts']=={'reviewed':480,'pending':368})
    arithmetic={'greaterAC':15+max(2,4)==19,'mundaneFireHalf':17//2==8,'physicalHalfMixed':13//2+7==13,'STR18to22':(22-10)//2-(18-10)//2==2,'STR23Cap24':23+min(4,max(0,24-23))==24,'STR26NotLowered':26+min(4,max(0,24-26))==26,'CON6Bases':sum(max(1,b-2) for b in [6,1])==5,'CON10Bases':sum(max(1,b) for b in [6,1])==7,'capacityClamp':min(7,5)==5,'petrifiedBodyOnly':180*10==1800,'petrifiedSlashing':14//2==7,'EarthstepBudget':20+10==30,'WindWalkRoster':1+10==11}
    for label,v in arithmetic.items():ck('Conditional original arithmetic '+label,v)
    root.mkdir();frozen=[]
    for b in sources.values():
        p=G/b['path'];ck('Current source unchanged '+b['path'],info(p)==b)
        dst=root/'sources'/b['path'];dst.parent.mkdir(parents=True,exist_ok=True);dst.write_bytes(p.read_bytes());ck('Exact frozen source '+b['path'],info(dst)['sha256']==b['sha256']);frozen.append({**b,'frozenCopy':dst.relative_to(G).as_posix()})
    result={'id':'BODY-DEFENSE-8-CONFERENCE-01','recordedAtUtc':datetime.now(timezone.utc).isoformat(),'status':'PREAUTHORSHIP_CONFERENCE_PREPARED_UNSENT; original full proposals preserved; no major new systemic choice selected.','developmentDirection':'video-game-only','records':records,'all16OriginalScenarios':cases,'completeOriginalSharedProposalsUnchanged':list(shared.values()),'sharedRouting':'Original shared proposals are history. Only source-qualified casting, clocks, defenses and body procedures apply to these identities; companions, zombieProfile, materialLedger, teleport-group or other card-only exceptions grant nothing here. Current accepted exact sources control inherited scopes.','currentAcceptedInterfaceComparisons':inherited,'completeAcceptedCounterparts':counterparts,'completePendingCounterparts':pending,'semanticDelta':semantic,'questions':questions,'findings':findings,'riskCounts':{'B':2,'C':6},'currentVectors':[],'currentVectorScope':'Zero new complete current vectors at this preauthorship stage. Sixteen original scenario obligations and conditional arithmetic are preserved, not represented as sourced/executed game encounters. After genuine design decisions, author complete legal class/actions/geometry/roll/HP/cargo cases.','sourceBindings':list(sources.values()),'countsUnchanged':{'reviewed':480,'pending':368},'newRuleAdoptions':0,'runtimeTestsExecuted':0,'humanPlaytests':0,'cosmologyDecisions':0,'sourceInformationDeleted':0}
    out.write_bytes(encoded(result))
    report.write_bytes(encoded({'candidate':info(out),'checks':checks,'checkCount':len(checks),'sourceCount':len(sources),'completeOriginalProcedures':8,'completeOriginalCases':16,'newCurrentVectors':0,'genuineQuestions':14,'failures':0,'validationScope':'Source integrity, exact preservation, current membership and conditional arithmetic only; actual full semantic review/conference not yet returned.'}))
    manifest={'candidate':info(out),'check':info(report),'files':list(sources.values()),'frozenSources':frozen,'sourceCount':len(sources),'counts':{'spells':8,'originalCases':16,'questions':14,'newCurrentVectors':0},'newRuleAdoptions':0}
    (root/'MANIFEST.json').write_bytes(encoded(manifest))
    (root/'README.md').write_text('''# Body/defense8 preauthorship conference01

Read the candidate's eight complete original proposals, exact catalog/Core/access records, sixteen original scenario obligations, accepted full counterparts, semantic delta and all fourteen explicit questions. This is a design conference before new current-case authorship, not an exact acceptance request. Zero new current encounter vectors are supplied. Original arithmetic remains conditional; no unsupplied attacks, healing, flight profile, severing event or class feature is claimed as executed.

Two interaction-heavy defense spells and six systemic body spells are grouped because they share actual body/form/HP interfaces. Do not reopen accepted movement, body/meld ceilings, maximum-HP clamp, native Petrified, hard-control admission, Gaseous Form, Null or AC6/DE4. Address only actual source conflicts/new local completions. In particular: broad nonmagical resistance keeps Core Corruption restrictions; Metaburst never recomputes fixed historical meld ceilings; its proposed reserve is not accepted Eye of Judgement authority; permanent stone needs explicit local intake/rest handling; Earthstep's recorded retreat is a new exception and needs whole-body geometry; Wind Walk cannot invent unsupplied root-size profiles.

Return downloadable REVIEW.json, VERDICT.md and full source-linked proposed procedure replacements for any changes. Give one disposition per spell and per question. Preserve every original case ID/obligation and exact source. Recommendations are not selected rules; resolve scope explicitly. After this actual conference, the selected current procedures and complete legal numerical cases will need exact review.480 reviewed/368 pending, all75 domain gates and cosmology/runtime/human/balance/release remain unchanged.
''',encoding='utf8',newline='\n')
    with zipfile.ZipFile(archive,'x',zipfile.ZIP_DEFLATED,compresslevel=9) as z:
        for name in ['README.md','MANIFEST.json']:z.write(root/name,name)
        z.write(out,'CANDIDATE.json');z.write(report,'PREFLIGHT.json')
        for b in frozen:z.write(G/b['frozenCopy'],'sources/'+b['path'])
    with zipfile.ZipFile(archive) as z:
        ck('ZIP CRC',z.testzip() is None)
        assert z.read('CANDIDATE.json')==out.read_bytes()
        for b in frozen:assert z.read('sources/'+b['path'])==(G/b['frozenCopy']).read_bytes()
    b=info(archive)
    req.write_text(f'Please hold a source-preserving preauthorship conference for Body/Defense8 using {archive.name} ({b["bytes"]} bytes; SHA256 {b["sha256"]}). It contains8 complete original procedures,16 original scenario obligations,14 genuine questions and full exact accepted/source counterparts. Zero new current encounter vectors are submitted; original conditional arithmetic is not runtime or full reachability proof. Read all8 spells and14questions: Greater Stoneflesh,Ironskin Legion,Formlock,Petrify Limb,Metaburst,Flesh to Stone,Earthstep,Wind Walk. Decide their scoped forks explicitly, keeping inherited interfaces closed. Especially preserve Core Corruption limits and fixed meld ceilings; distinguish temporary CON/real resource holders from the unaccepted Eye of Judgement reserve; decide local permanent-stone metabolism, finite whole-body Earthstep retreat and Wind Walk root-size/individual lifecycle. Return downloadable per-spell/per-question dispositions and full exact source-linked replacement procedures if changes are needed. Preserve all originals. This is not final exact acceptance,adoption,runtime,human,balance,cosmology or whole-game approval.480/368 unchanged.\n',encoding='utf8',newline='\n')
    prep.write_bytes(encoded({'archive':b,'candidate':info(out),'manifest':info(root/'MANIFEST.json'),'check':info(report),'request':info(req),'sourceCount':len(sources),'allArchiveSourcesVerified':True,'status':'Prepared UNSENT; actual companion/life10 conference remains active.','newRuleAdoptions':0}))
    print(json.dumps({'archive':b,'candidate':info(out),'preparation':info(prep),'sources':len(sources),'preflightChecks':len(checks)-1,'originalCases':16,'questions':14}))


if __name__=='__main__':main()
